def add(firstNumber, secondNumber, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0496000" if __import__("os").path.isdir("./environment_mix/0496000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    def _iso(dt): return dt.isoformat() + "Z"
    today = datetime.datetime(now.year, now.month, now.day)

    tool_name = "add"

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    # Ambient auth: pick any active key that allows this tool.
    usable_keys = []
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        allowed = k.get("allowed_tools")
        if isinstance(allowed, list) and len(allowed) > 0 and tool_name not in allowed:
            continue
        # Must have numeric limits
        if not isinstance(k.get("quota_calls_per_day"), int) or k.get("quota_calls_per_day") < 0:
            continue
        if not isinstance(k.get("rate_limit_per_minute"), int) or k.get("rate_limit_per_minute") < 0:
            continue
        usable_keys.append(k)

    if not usable_keys:
        # No key can serve this request; record nothing (cannot satisfy FK).
        return _err("UNAUTHORIZED", "No active API key available for this tool.")

    # Prefer key with highest quota to reduce chance of quota errors.
    usable_keys.sort(key=lambda r: (r.get("quota_calls_per_day", 0), r.get("rate_limit_per_minute", 0)), reverse=True)

    tool_executions = _load("tool_executions.json")
    if not isinstance(tool_executions, list):
        tool_executions = []
    usage_daily = _load("usage_daily.json")
    if not isinstance(usage_daily, list):
        usage_daily = []
    execution_numbers = _load("execution_numbers.json")
    if not isinstance(execution_numbers, list):
        execution_numbers = []

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _get_daily_row(api_key_id):
        # date bucket stored as datetime-like; compare by YYYY-MM-DD
        target = today.date()
        for row in usage_daily:
            if not isinstance(row, dict):
                continue
            if row.get("api_key_id") != api_key_id:
                continue
            d = row.get("date")
            if isinstance(d, str):
                try:
                    if d.endswith("Z"):
                        d2 = datetime.datetime.fromisoformat(d[:-1])
                    else:
                        d2 = datetime.datetime.fromisoformat(d)
                    if d2.date() == target:
                        return row
                except Exception:
                    continue
            elif isinstance(d, (datetime.datetime, datetime.date)):
                try:
                    if isinstance(d, datetime.datetime):
                        if d.date() == target:
                            return row
                    else:
                        if d == target:
                            return row
                except Exception:
                    continue
        return None

    def _calls_last_minute(api_key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for ex in tool_executions:
            if not isinstance(ex, dict):
                continue
            if ex.get("api_key_id") != api_key_id:
                continue
            ts = ex.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]) if ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
            except Exception:
                continue
            if dt >= cutoff:
                c += 1
        return c

    def _append_execution(api_key_id, status, request_params, result_number=None, result_meta=None,
                          error_code=None, error_message=None, numbers_count=None, latency_ms=None):
        ex_id = _gen_id("exec")
        ex = {
            "id": ex_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "status": status,
            "request_params": request_params,
            "result_number": result_number,
            "result_meta": result_meta,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "numbers_count": numbers_count,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tool_executions.append(ex)
        return ex

    def _set_status(ex, new_status):
        transitions = {
            "received": ["validated", "failed"],
            "validated": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        cur = ex.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            return False
        ex["status"] = new_status
        ex["updated_at"] = _iso(datetime.datetime.utcnow().replace(microsecond=0))
        return True

    def _upsert_usage(api_key_id, succeeded, numbers_inc):
        row = _get_daily_row(api_key_id)
        if row is None:
            row = {
                "id": _gen_id("uday"),
                "api_key_id": api_key_id,
                "date": _iso(today),
                "calls_total": 0,
                "calls_succeeded": 0,
                "calls_failed": 0,
                "numbers_total": 0,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            usage_daily.append(row)
        row["calls_total"] = int(row.get("calls_total", 0)) + 1
        if succeeded:
            row["calls_succeeded"] = int(row.get("calls_succeeded", 0)) + 1
        else:
            row["calls_failed"] = int(row.get("calls_failed", 0)) + 1
        row["numbers_total"] = int(row.get("numbers_total", 0)) + int(numbers_inc or 0)
        row["updated_at"] = _iso(datetime.datetime.utcnow().replace(microsecond=0))
        # Keep invariant if possible
        if row["calls_total"] != row["calls_succeeded"] + row["calls_failed"]:
            row["calls_total"] = row["calls_succeeded"] + row["calls_failed"]

    def _update_key_last_used(api_key_row):
        api_key_row["last_used_at"] = _iso(datetime.datetime.utcnow().replace(microsecond=0))
        api_key_row["updated_at"] = _iso(datetime.datetime.utcnow().replace(microsecond=0))

    # Validate input types
    if not (isinstance(firstNumber, (int, float)) and not isinstance(firstNumber, bool)):
        # Choose any key to record failure; pick best usable
        k = usable_keys[0]
        ex = _append_execution(k["id"], "received", {"firstNumber": firstNumber, "secondNumber": secondNumber},
                              error_code="VALIDATION_ERROR", error_message="firstNumber must be a number.")
        _set_status(ex, "failed")
        ex["latency_ms"] = int((time.time() - t0) * 1000)
        _upsert_usage(k["id"], False, 0)
        _save("tool_executions.json", tool_executions)
        _save("usage_daily.json", usage_daily)
        return _err("VALIDATION_ERROR", "firstNumber must be a number.")
    if not (isinstance(secondNumber, (int, float)) and not isinstance(secondNumber, bool)):
        k = usable_keys[0]
        ex = _append_execution(k["id"], "received", {"firstNumber": firstNumber, "secondNumber": secondNumber},
                              error_code="VALIDATION_ERROR", error_message="secondNumber must be a number.")
        _set_status(ex, "failed")
        ex["latency_ms"] = int((time.time() - t0) * 1000)
        _upsert_usage(k["id"], False, 0)
        _save("tool_executions.json", tool_executions)
        _save("usage_daily.json", usage_daily)
        return _err("VALIDATION_ERROR", "secondNumber must be a number.")

    # Find a key that passes rate/quota and record against it.
    chosen = None
    quota_blocked = True
    rate_blocked = True
    for k in usable_keys:
        api_key_id = k["id"]
        # rate limit
        rl = int(k.get("rate_limit_per_minute", 0))
        if rl > 0 and _calls_last_minute(api_key_id) >= rl:
            continue
        rate_blocked = False
        # quota
        q = int(k.get("quota_calls_per_day", 0))
        row = _get_daily_row(api_key_id)
        used = int(row.get("calls_total", 0)) if row else 0
        if used + 1 > q:
            continue
        quota_blocked = False
        chosen = k
        break

    if chosen is None:
        k = usable_keys[0]
        # Determine primary refusal reason
        code = "RATE_LIMIT" if rate_blocked and not quota_blocked else "QUOTA_EXCEEDED"
        msg = "Rate limit exceeded." if code == "RATE_LIMIT" else "Daily quota exceeded."
        ex = _append_execution(k["id"], "received", {"firstNumber": firstNumber, "secondNumber": secondNumber},
                              error_code=code, error_message=msg)
        _set_status(ex, "failed")
        ex["latency_ms"] = int((time.time() - t0) * 1000)
        _upsert_usage(k["id"], False, 0)
        _save("tool_executions.json", tool_executions)
        _save("usage_daily.json", usage_daily)
        return _err(code, msg)

    # All prerequisites met; execute with proper lifecycle transitions.
    api_key_id = chosen["id"]
    request_params = {"firstNumber": float(firstNumber), "secondNumber": float(secondNumber)}
    ex = _append_execution(api_key_id, "received", request_params)
    if not _set_status(ex, "validated"):
        ex["error_code"] = "INVALID_TRANSITION"
        ex["error_message"] = "Illegal lifecycle transition."
        _set_status(ex, "failed") if ex["status"] != "failed" else None

    result = request_params["firstNumber"] + request_params["secondNumber"]
    if ex["status"] != "failed":
        if not _set_status(ex, "succeeded"):
            ex["error_code"] = "INVALID_TRANSITION"
            ex["error_message"] = "Illegal lifecycle transition."
            _set_status(ex, "failed")
        else:
            ex["result_number"] = result
            ex["error_code"] = None
            ex["error_message"] = None

    ex["latency_ms"] = int((time.time() - t0) * 1000)
    succeeded = ex["status"] == "succeeded"
    if not succeeded:
        ex["result_number"] = None
        if not ex.get("error_code"):
            ex["error_code"] = "FAILED"
            ex["error_message"] = "Execution failed."
    _upsert_usage(api_key_id, succeeded, 0)
    if succeeded:
        _update_key_last_used(chosen)

    _save("tool_executions.json", tool_executions)
    _save("usage_daily.json", usage_daily)
    _save("api_keys.json", api_keys)
    # execution_numbers unchanged for this tool

    if succeeded:
        return {"result": ex["result_number"], "execution_id": ex["id"]}
    return _err(ex.get("error_code") or "FAILED", ex.get("error_message") or "Execution failed.", execution_id=ex["id"])

