            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]) if ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
            except Exception:
                continue
            if dt >= cutoff:
                c += 1
        return c

    def _append_execution(api_key_id, status, request_params, result_number=None, result_meta=None,
                          error_code=None, error_message=None, numbers_count=None, latency_ms=None):
