        req["secondNumber"] = _extra.get("secondNumber")
        ex = _append_execution(k["id"], "received", req, error_code="VALIDATION_ERROR",
                              error_message="Parameter name is case-sensitive: use 'SecondNumber', not 'secondNumber'.")
        _set_status(ex, "failed")
