def sum(numbers, **_extra):
    import json, os, datetime, time, uuid, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0496000" if __import__("os").path.isdir("./environment_mix/0496000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    today = now.date()
    today_bucket = datetime.datetime(today.year, today.month, today.day)

    TOOL = "sum"

    api_keys = _load("api_keys.json")
    executions = _load("tool_executions.json")
    exec_numbers = _load("execution_numbers.json")
    usage_daily = _load("usage_daily.json")

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _find_working_key_for_tool(tool_name):
        # Ambient auth: pick any active key that can serve the request
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            allowed = k.get("allowed_tools")
            if isinstance(allowed, list) and len(allowed) > 0 and tool_name not in allowed:
                continue
            # must have required quota/rate fields
            if not isinstance(k.get("quota_calls_per_day"), int) or k.get("quota_calls_per_day") < 0:
                continue
            if not isinstance(k.get("quota_numbers_per_call_max"), int) or k.get("quota_numbers_per_call_max") < 1:
                continue
            if not isinstance(k.get("rate_limit_per_minute"), int) or k.get("rate_limit_per_minute") < 0:
                continue
            if not isinstance(k.get("id"), str) or not k["id"]:
                continue
            return k
        return None

    def _usage_row_for(api_key_id):
        for r in usage_daily:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            d = _parse_dt(r.get("date"))
            if d and d.date() == today:
                return r
        return None

    def _count_recent_calls(api_key_id):
        # approximate per-minute limit using tool_executions timestamps
        cutoff = now - datetime.timedelta(seconds=60)
        n = 0
        for e in executions:
            if not isinstance(e, dict):
                continue
            if e.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(e.get("created_at"))
            if dt and dt >= cutoff:
                n += 1
        return n

    def _append_execution(row):
        executions.append(row)
        _save("tool_executions.json", executions)

    def _update_execution(execution_id, **fields):
        for e in executions:
            if isinstance(e, dict) and e.get("id") == execution_id:
                e.update(fields)
                _save("tool_executions.json", executions)
                return True
        return False

    def _upsert_usage(api_key_id, succeeded, numbers_count):
        r = _usage_row_for(api_key_id)
        ts = _iso(now)
        if r is None:
            r = {
                "id": _gen_id("ud"),
                "api_key_id": api_key_id,
                "date": _iso(today_bucket),
                "calls_total": 0,
                "calls_succeeded": 0,
                "calls_failed": 0,
                "numbers_total": 0,
                "created_at": ts,
                "updated_at": ts,
            }
            usage_daily.append(r)
        r["calls_total"] = int(r.get("calls_total") or 0) + 1
        if succeeded:
            r["calls_succeeded"] = int(r.get("calls_succeeded") or 0) + 1
        else:
            r["calls_failed"] = int(r.get("calls_failed") or 0) + 1
        if numbers_count is not None:
            r["numbers_total"] = int(r.get("numbers_total") or 0) + int(numbers_count)
        r["updated_at"] = ts
        _save("usage_daily.json", usage_daily)

    def _create_execution_numbers(execution_id, nums):
        created = 0
        ts = _iso(now)
        # enforce fk and unique(execution_id, position)
        existing_positions = set()
        for r in exec_numbers:
            if isinstance(r, dict) and r.get("execution_id") == execution_id:
                existing_positions.add(r.get("position"))
        for i, v in enumerate(nums):
            if i in existing_positions:
                return False
            exec_numbers.append({
                "id": _gen_id("en"),
                "execution_id": execution_id,
                "position": i,
                "value": v,
                "created_at": ts,
                "updated_at": ts,
            })
            created += 1
        _save("execution_numbers.json", exec_numbers)
        return created == len(nums)

    # Validate request params schema: additionalProperties=false with only numbers
    if _extra:
        # unexpected properties
        return _err("VALIDATION_ERROR", "Unexpected properties provided.", unexpected=list(_extra.keys()))

    if not isinstance(numbers, list):
        return _err("VALIDATION_ERROR", "`numbers` must be an array of numbers.")
    if len(numbers) < 1:
        return _err("VALIDATION_ERROR", "`numbers` must have at least 1 item.")

