    clean_numbers = []
    for idx, v in enumerate(numbers):
        if isinstance(v, bool) or not isinstance(v, (int, float)) or (isinstance(v, float) and (math.isnan(v) or math.isinf(v))):
            return _err("VALIDATION_ERROR", f"`numbers[{idx}]` must be a finite number.")
        clean_numbers.append(float(v) if isinstance(v, int) else v)

