        "tool_name": TOOL,
        "status": "received",
        "request_params": {"numbers": clean_numbers},
        "result_number": None,
        "result_meta": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "numbers_count": len(clean_numbers),
        "created_at": ts,
        "updated_at": ts,
    }
    _append_execution(execution)

    if api_key.get("status") != "active":
        _update_execution(exec_id,
                          status="failed",
                          error_code="KEY_INACTIVE",
                          error_message="API key is not active.",
                          updated_at=_iso(datetime.datetime.utcnow().replace(microsecond=0)),
                          latency_ms=int((time.time() - t0) * 1000))
        _upsert_usage(api_key_id, succeeded=False, numbers_count=len(clean_numbers))
        return _err("UNAUTHORIZED", "API key is not active.", error_code="KEY_INACTIVE")

    allowed = api_key.get("allowed_tools")
    if isinstance(allowed, list) and len(allowed) > 0 and TOOL not in allowed:
        _update_execution(exec_id,
                          status="failed",
                          error_code="TOOL_NOT_ALLOWED",
                          error_message="This API key is not allowed to use the requested tool.",
                          updated_at=_iso(datetime.datetime.utcnow().replace(microsecond=0)),
                          latency_ms=int((time.time() - t0) * 1000))
        _upsert_usage(api_key_id, succeeded=False, numbers_count=len(clean_numbers))
        return _err("UNAUTHORIZED", "Tool not allowed for this API key.", error_code="TOOL_NOT_ALLOWED")

    rlm = api_key.get("rate_limit_per_minute")
    if isinstance(rlm, int) and rlm >= 0:
        recent = _count_recent_calls(api_key_id)
        if recent > rlm:
            _update_execution(exec_id,
                              status="failed",
                              error_code="RATE_LIMIT",
                              error_message="Rate limit exceeded.",
                              updated_at=_iso(datetime.datetime.utcnow().replace(microsecond=0)),
                              latency_ms=int((time.time() - t0) * 1000))
            _upsert_usage(api_key_id, succeeded=False, numbers_count=len(clean_numbers))
            return _err("RATE_LIMIT", "Rate limit exceeded.")

    maxn = api_key.get("quota_numbers_per_call_max")
    if isinstance(maxn, int) and len(clean_numbers) > maxn:
        _update_execution(exec_id,
                          status="failed",
                          error_code="QUOTA_EXCEEDED",
                          error_message="Too many numbers for this API key.",
                          updated_at=_iso(datetime.datetime.utcnow().replace(microsecond=0)),
                          latency_ms=int((time.time() - t0) * 1000))
        _upsert_usage(api_key_id, succeeded=False, numbers_count=len(clean_numbers))
        return _err("QUOTA_EXCEEDED", "Too many numbers in a single call.")

    quota_day = api_key.get("quota_calls_per_day")
    if isinstance(quota_day, int):
        ur = _usage_row_for(api_key_id)
        current_calls = int(ur.get("calls_total") or 0) if ur else 0
        if current_calls + 1 > quota_day:
            _update_execution(exec_id,
                              status="failed",
                              error_code="QUOTA_EXCEEDED",
                              error_message="Daily call quota exceeded.",
                              updated_at=_iso(datetime.datetime.utcnow().replace(microsecond=0)),
                              latency_ms=int((time.time() - t0) * 1000))
            _upsert_usage(api_key_id, succeeded=False, numbers_count=len(clean_numbers))
            return _err("QUOTA_EXCEEDED", "Daily call quota exceeded.")

    _update_execution(exec_id, status="validated", updated_at=_iso(datetime.datetime.utcnow().replace(microsecond=0)))

    if not _create_execution_numbers(exec_id, clean_numbers):
        _update_execution(exec_id,
                          status="failed",
                          error_code="CONFLICT",
                          error_message="Could not create execution number rows.",
                          updated_at=_iso(datetime.datetime.utcnow().replace(microsecond=0)),
                          latency_ms=int((time.time() - t0) * 1000),
                          result_number=None)
        _upsert_usage(api_key_id, succeeded=False, numbers_count=len(clean_numbers))
        return _err("CONFLICT", "Execution number rows conflict.")

    sorted_nums = sorted(clean_numbers)
    n = len(sorted_nums)
    if n % 2 == 1:
        result = sorted_nums[n // 2]
        meta = {"sorted": True, "even_length": False}
    else:
        a = sorted_nums[(n // 2) - 1]
        b = sorted_nums[n // 2]
        result = (a + b) / 2.0
        meta = {"sorted": True, "even_length": True, "middle_values": [a, b]}

    latency = int((time.time() - t0) * 1000)
    _update_execution(exec_id,
                      status="succeeded",
                      result_number=result,
                      result_meta=meta,
                      error_code=None,
                      error_message=None,
                      latency_ms=latency,
                      updated_at=_iso(datetime.datetime.utcnow().replace(microsecond=0)))

    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = _iso(datetime.datetime.utcnow().replace(microsecond=0))
            k["updated_at"] = _iso(datetime.datetime.utcnow().replace(microsecond=0))
            _save("api_keys.json", api_keys)
            break

    _upsert_usage(api_key_id, succeeded=True, numbers_count=len(clean_numbers))

    return {
        "execution_id": exec_id,
        "tool_name": TOOL,
        "status": "succeeded",
        "result": result,
        "meta": meta,
        "numbers_count": len(clean_numbers),
        "latency_ms": latency,
    }

def mode(numbers, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0496000" if __import__("os").path.isdir("./environment_mix/0496000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    TOOL = "mode"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso_dt(s):
        if not isinstance(s, str) or not s:
            return None
        v = s.strip()
        if v.endswith("Z"):
            v = v[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(v)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _day_bucket_iso(now_utc):
        d = now_utc.date()
        return _isoz(datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc).replace(microsecond=0))

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_number(x):
        if isinstance(x, bool):
            return False
        if not isinstance(x, (int, float)):
            return False
        try:
            return math.isfinite(float(x))
        except Exception:
            return False

    def _get_usage_row(usage_rows, api_key_id, date_iso, now_iso):
        for r in usage_rows:
            if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("date") == date_iso:
                return r
        r = {
            "id": _gen_id("mmu"),
            "api_key_id": api_key_id,
            "date": date_iso,
            "calls_total": 0,
            "calls_succeeded": 0,
            "calls_failed": 0,
            "numbers_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
            "status": "open",
        }
        usage_rows.append(r)
        return r

    def _pick_api_key(api_keys):
        # Ambient auth: choose an API key that can serve this request.
        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            allowed = k.get("allowed_tools")
            if isinstance(allowed, list) and len(allowed) > 0 and TOOL not in allowed:
                continue
            # Require quota fields to exist and be sane
            if not isinstance(k.get("quota_calls_per_day"), int) or k.get("quota_calls_per_day") < 0:
                continue
            if not isinstance(k.get("rate_limit_per_minute"), int) or k.get("rate_limit_per_minute") < 0:
                continue
            if not isinstance(k.get("quota_numbers_per_call_max"), int) or k.get("quota_numbers_per_call_max") < 1:
                continue
            candidates.append(k)
        if not candidates:
            return None
        # Prefer the key with the largest daily quota, then largest per-call numbers quota
        candidates.sort(key=lambda r: (r.get("quota_calls_per_day", 0), r.get("quota_numbers_per_call_max", 1)), reverse=True)
        return candidates[0]

    def _check_rate_limit(executions_rows, api_key_id, now_utc, per_minute):
        if per_minute <= 0:
            return True, None
        window_start = now_utc - datetime.timedelta(seconds=60)
        cnt = 0
        for e in executions_rows:
            if not isinstance(e, dict):
                continue
            if e.get("api_key_id") != api_key_id:
                continue
            ca = e.get("created_at")
            dt = _parse_iso_dt(ca) if isinstance(ca, str) else None
            if dt is None:
                continue
            if dt >= window_start:
                cnt += 1
        if cnt + 1 > per_minute:
            retry_after = 1
            return False, retry_after
        return True, None

    def _create_execution(exec_rows, api_key_id, status, request_params, numbers_count, now_iso, error_code=None, error_message=None, result_number=None, result_meta=None, latency_ms=None):
        row = {
            "id": _gen_id("mmx"),
            "api_key_id": api_key_id,
            "tool_name": TOOL,
            "status": status,
            "request_params": request_params,
            "result_number": result_number,
            "result_meta": result_meta,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "numbers_count": numbers_count,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        exec_rows.append(row)
        return row

    def _create_execution_numbers(execution_numbers_rows, execution_id, nums, now_iso):
        created = 0
        existing_positions = set()
        for r in execution_numbers_rows:
            if isinstance(r, dict) and r.get("execution_id") == execution_id and isinstance(r.get("position"), int):
                existing_positions.add(r["position"])
        for i, v in enumerate(nums):
            if i in existing_positions:
                # Shouldn't happen for a new execution_id, but keep integrity.
                continue
            execution_numbers_rows.append({
                "id": _gen_id("mmn"),
                "execution_id": execution_id,
                "position": i,
                "value": v,
                "created_at": now_iso,
                "updated_at": now_iso,
                "status": "active",
            })
            created += 1
        return created

    now = _utcnow()
    now_iso = _isoz(now)
    date_iso = _day_bucket_iso(now)

    # Load store
    api_keys = _load("api_keys.json")
    exec_rows = _load("tool_executions.json")
    usage_rows = _load("usage_daily.json")
    execution_numbers_rows = _load("execution_numbers.json")

    if not isinstance(api_keys, list) or not isinstance(exec_rows, list) or not isinstance(usage_rows, list) or not isinstance(execution_numbers_rows, list):
        return _err("NOT_FOUND", "Datastore is not initialized")

    api_key = _pick_api_key(api_keys)
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this operation")

    api_key_id = api_key.get("id")

    # Validate request schema
    if numbers is None:
        return _err("VALIDATION_ERROR", "Missing required property 'numbers'")
    if not isinstance(numbers, list):
        return _err("VALIDATION_ERROR", "'numbers' must be an array")
    if len(numbers) < 1:
        return _err("VALIDATION_ERROR", "'numbers' must not be empty")

    # Enforce per-call numbers quota
    if len(numbers) > int(api_key.get("quota_numbers_per_call_max", 0)):
        # Must be QUOTA_EXCEEDED per rules
        # Still record attempt as failed execution + usage increment.
        pass

    # Authenticate/authorize key + create received execution early
    received_params = {"numbers": numbers}
    execution = _create_execution(
        exec_rows=exec_rows,
        api_key_id=api_key_id,
        status="received",
        request_params=received_params,
        numbers_count=len(numbers),
        now_iso=now_iso,
        error_code=None,
        error_message=None,
        result_number=None,
        result_meta=None,
        latency_ms=None,
    )

    def _finalize_failed(code, msg, retry_after=None):
        execution["status"] = "failed"
        execution["error_code"] = code
        execution["error_message"] = msg
        execution["result_number"] = None
        execution["updated_at"] = _isoz(_utcnow())
        execution["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        # usage upsert + increment
        ur = _get_usage_row(usage_rows, api_key_id, date_iso, now_iso)
        ur["calls_total"] = int(ur.get("calls_total", 0)) + 1
        ur["calls_failed"] = int(ur.get("calls_failed", 0)) + 1
        ur["calls_succeeded"] = int(ur.get("calls_succeeded", 0))
        # calls_total must equal succeeded+failed
        ur["calls_total"] = int(ur["calls_succeeded"]) + int(ur["calls_failed"])
        # numbers_total increments by numbers_count for array tools even when failed
        ur["numbers_total"] = int(ur.get("numbers_total", 0)) + int(execution.get("numbers_count") or 0)
        ur["updated_at"] = _isoz(_utcnow())
        # persist
        _save("tool_executions.json", exec_rows)
        _save("usage_daily.json", usage_rows)
        if retry_after is not None:
            return _err("RATE_LIMIT", msg, retry_after_seconds=retry_after, execution_id=execution["id"])
        return _err(code, msg, execution_id=execution["id"])

    # Key must be active (for this tool, we already picked active; keep invariant)
    if api_key.get("status") != "active":
        return _finalize_failed("KEY_INACTIVE", "API key is not active")

    # Allowed tools check
    allowed = api_key.get("allowed_tools")
    if isinstance(allowed, list) and len(allowed) > 0 and TOOL not in allowed:
        return _finalize_failed("TOOL_NOT_ALLOWED", "tool not allowed for this API key")

    # Validate all numbers are finite
    for i, v in enumerate(numbers):
        if not _is_number(v):
            return _finalize_failed("VALIDATION_ERROR", f"numbers[{i}] must be a finite number")

    # Rate limit enforcement
    ok, retry_after = _check_rate_limit(exec_rows, api_key_id, now, int(api_key.get("rate_limit_per_minute", 0)))
    if not ok:
        return _finalize_failed("RATE_LIMITED", f"too many requests; retry after {retry_after}s", retry_after=retry_after)

    # Daily quota enforcement (counts all attempts)
    ur_pre = _get_usage_row(usage_rows, api_key_id, date_iso, now_iso)
    if int(ur_pre.get("calls_total", 0)) + 1 > int(api_key.get("quota_calls_per_day", 0)):
        return _finalize_failed("QUOTA_EXCEEDED", "daily call quota exceeded for UTC date")

    # Per-call numbers quota
    if len(numbers) > int(api_key.get("quota_numbers_per_call_max", 0)):
        return _finalize_failed("QUOTA_EXCEEDED", f"numbers length {len(numbers)} exceeds per-call limit for this API key")

    # Transition to validated
    execution["status"] = "validated"
    execution["updated_at"] = _isoz(_utcnow())

    # Create execution_numbers children
    created_children = _create_execution_numbers(execution_numbers_rows, execution["id"], numbers, now_iso)
    execution["numbers_count"] = len(numbers)  # must match original list length

    if created_children != len(numbers):
        # Integrity issue: fail and do not claim success
        return _finalize_failed("CONFLICT", "execution_numbers could not be fully recorded due to a uniqueness conflict")

    # Compute mode; conflict on tie for highest frequency
    freq = {}
    for v in numbers:
        freq[v] = freq.get(v, 0) + 1
    max_count = max(freq.values()) if freq else 0
    modes = [k for k, c in freq.items() if c == max_count]
    if len(modes) != 1:
        # tie or no unique mode
        # Persist children are already written into memory; still record execution failed per rule.
        # Keep result_number null.
        # Also save execution_numbers so audit retains inputs.
        _save("execution_numbers.json", execution_numbers_rows)
        return _finalize_failed("CONFLICT", "no unique mode (tie for highest frequency)")

    result = float(modes[0])

    # Success transition to succeeded
    execution["status"] = "succeeded"
    execution["result_number"] = result
    execution["error_code"] = None
    execution["error_message"] = None
    execution["result_meta"] = {"frequency": max_count, "unique_values": len(freq)}
    execution["updated_at"] = _isoz(_utcnow())
    execution["latency_ms"] = max(0, int((time.time() - t0) * 1000))

    # usage upsert + increment
    ur = _get_usage_row(usage_rows, api_key_id, date_iso, now_iso)
    ur["calls_total"] = int(ur.get("calls_total", 0)) + 1
    ur["calls_succeeded"] = int(ur.get("calls_succeeded", 0)) + 1
    ur["calls_failed"] = int(ur.get("calls_failed", 0))
    ur["calls_total"] = int(ur["calls_succeeded"]) + int(ur["calls_failed"])
    ur["numbers_total"] = int(ur.get("numbers_total", 0)) + len(numbers)
    ur["updated_at"] = _isoz(_utcnow())

    # api_key last_used_at for successful authenticated request
    api_key["last_used_at"] = _isoz(_utcnow())
    api_key["updated_at"] = _isoz(_utcnow())

    # Persist
    _save("execution_numbers.json", execution_numbers_rows)
    _save("tool_executions.json", exec_rows)
    _save("usage_daily.json", usage_rows)
    _save("api_keys.json", api_keys)

    return {
        "tool_name": TOOL,
        "execution_id": execution["id"],
        "status": execution["status"],
        "result": execution["result_number"],
        "meta": execution["result_meta"],
        "numbers_count": execution["numbers_count"],
        "latency_ms": execution["latency_ms"],
    }

