            if dt and dt >= cutoff:
                cnt += 1
        return cnt

    def _key_allows_tool(k):
        allowed = k.get("allowed_tools")
        return not (isinstance(allowed, list) and len(allowed) > 0 and TOOL not in allowed)

    def _choose_key_for_request():
        candidates = [k for k in api_keys if isinstance(k, dict) and isinstance(k.get("id"), str) and k.get("id")]
        if not candidates:
            return None, None

        def usable(k):
            if k.get("status") != "active":
                return False
            if not _key_allows_tool(k):
                return False
            rlp = k.get("rate_limit_per_minute")
            if not isinstance(rlp, int) or rlp < 0:
                return False
            if rlp > 0 and _count_calls_last_minute(k["id"]) >= rlp:
                return False
            q = k.get("quota_calls_per_day")
            if not isinstance(q, int) or q < 0:
                return False
            u = _get_or_create_usage_row(k["id"])
            return (u.get("calls_total", 0) + 1) <= q

        for k in candidates:
            if usable(k):
                return k, None

        record_key = None
        for k in candidates:
            if k.get("status") == "active" and _key_allows_tool(k):
                record_key = k
                break
        if record_key is None:
            record_key = candidates[0]

        if record_key.get("status") != "active":
            return record_key, ("KEY_INACTIVE", "API key is not active", "UNAUTHORIZED")
        if not _key_allows_tool(record_key):
            return record_key, ("TOOL_NOT_ALLOWED", f"tool '{TOOL}' not allowed for this API key", "UNAUTHORIZED")

        rlp = record_key.get("rate_limit_per_minute")
        if isinstance(rlp, int) and rlp > 0 and _count_calls_last_minute(record_key["id"]) >= rlp:
            return record_key, ("RATE_LIMITED", "too many requests; retry after 1s", "RATE_LIMIT")

        q = record_key.get("quota_calls_per_day")
        if isinstance(q, int) and q >= 0:
            u = _get_or_create_usage_row(record_key["id"])
            if u.get("calls_total", 0) + 1 > q:
                return record_key, ("QUOTA_EXCEEDED", "daily call quota exceeded for UTC date", "QUOTA_EXCEEDED")

        return record_key, ("UNAUTHORIZED", "no available API key could authorize this request", "UNAUTHORIZED")

    def _create_execution(api_key_id, status, request_params, result_number=None, result_meta=None, error_code=None, error_message=None):
        eid = _gen_id("mmx")
        row = {
            "id": eid,
            "api_key_id": api_key_id,
            "tool_name": TOOL,
            "status": status,
            "request_params": request_params,
            "result_number": result_number,
            "result_meta": result_meta,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": None,
            "numbers_count": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_execs.append(row)
        return row

    def _set_exec_status(exec_row, new_status, **fields):
        allowed = {"received": {"validated", "failed"}, "validated": {"succeeded", "failed"}, "succeeded": set(), "failed": set()}
        cur = exec_row.get("status")
        if cur not in allowed or new_status not in allowed[cur]:
            return False
        exec_row["status"] = new_status
        exec_row["updated_at"] = now_iso
        for k, v in fields.items():
            exec_row[k] = v
        return True

    def _upsert_usage_on_completion(api_key_id, succeeded):
        u = _get_or_create_usage_row(api_key_id)
        u["calls_total"] = int(u.get("calls_total", 0)) + 1
        if succeeded:
            u["calls_succeeded"] = int(u.get("calls_succeeded", 0)) + 1
        else:
            u["calls_failed"] = int(u.get("calls_failed", 0)) + 1
        u["updated_at"] = now_iso

    def _touch_key_last_used(api_key_row):
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso

    if not _is_number(number):
        k, _ = _choose_key_for_request()
        if k is None:
            return _err("UNAUTHORIZED", "no API key available")
        ex = _create_execution(k["id"], "received", {"number": number})
        _set_exec_status(ex, "failed", error_code="VALIDATION_ERROR", error_message="number must be a finite number", result_number=None)
        ex["latency_ms"] = int((time.time() - t0) * 1000)
        _upsert_usage_on_completion(k["id"], False)
        _save("tool_executions.json", tool_execs)
        _save("usage_daily.json", usage_daily)
        return _err("VALIDATION_ERROR", "number must be a finite number")

    api_key, auth_fail = _choose_key_for_request()
    if api_key is None:
        return _err("UNAUTHORIZED", "no API key available")

    if auth_fail is not None:
        err_code, err_msg, top_code = auth_fail
        ex = _create_execution(api_key["id"], "received", {"number": number})
        _set_exec_status(ex, "failed", error_code=err_code, error_message=err_msg, result_number=None)
        ex["latency_ms"] = int((time.time() - t0) * 1000)
        _upsert_usage_on_completion(api_key["id"], False)
        _save("tool_executions.json", tool_execs)
        _save("usage_daily.json", usage_daily)
        return _err(top_code, err_msg)

    ex = _create_execution(api_key["id"], "received", {"number": number})
    if not _set_exec_status(ex, "validated"):
        ex["latency_ms"] = int((time.time() - t0) * 1000)
        _save("tool_executions.json", tool_execs)
        return _err("INVALID_TRANSITION", "illegal execution status transition")

    result = math.floor(float(number))
    if not _set_exec_status(ex, "succeeded", result_number=result, result_meta=None, error_code=None, error_message=None):
        ex["latency_ms"] = int((time.time() - t0) * 1000)
        _save("tool_executions.json", tool_execs)
        return _err("INVALID_TRANSITION", "illegal execution status transition")

    ex["latency_ms"] = int((time.time() - t0) * 1000)
    _upsert_usage_on_completion(api_key["id"], True)
    _touch_key_last_used(api_key)

    _save("tool_executions.json", tool_execs)
    _save("usage_daily.json", usage_daily)
    _save("api_keys.json", api_keys)
    return {"result": result, "execution_id": ex["id"]}

def ceiling(number, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0496000" if __import__("os").path.isdir("./environment_mix/0496000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    TOOL = "ceiling"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_bucket(dt_utc):
        d = dt_utc.date()
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc).replace(microsecond=0)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_number(x):
        if isinstance(x, bool):
            return False
        if not isinstance(x, (int, float)):
            return False
        return math.isfinite(float(x))

    api_keys = _load("api_keys.json")
    tool_execs = _load("tool_executions.json")
    usage_daily = _load("usage_daily.json")

    now = _utcnow()
    now_iso = _isoz(now)
    day_bucket_iso = _isoz(_day_bucket(now))

    def _get_or_create_usage_row(api_key_id):
        for r in usage_daily:
            if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("date") == day_bucket_iso:
                return r
        r = {
            "id": _gen_id("mmu"),
            "api_key_id": api_key_id,
            "date": day_bucket_iso,
            "calls_total": 0,
            "calls_succeeded": 0,
            "calls_failed": 0,
            "numbers_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
            "status": "open",
        }
        usage_daily.append(r)
        return r

    def _count_calls_last_minute(api_key_id):
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for e in tool_execs:
            if not isinstance(e, dict) or e.get("api_key_id") != api_key_id:
                continue
            dt = _parse_iso_dt(e.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt

    def _key_allows_tool(k):
        allowed = k.get("allowed_tools")
        return not (isinstance(allowed, list) and len(allowed) > 0 and TOOL not in allowed)

    def _choose_key_for_request():
        candidates = [k for k in api_keys if isinstance(k, dict) and isinstance(k.get("id"), str) and k.get("id")]
        if not candidates:
            return None, None

        def usable(k):
            if k.get("status") != "active":
                return False
            if not _key_allows_tool(k):
                return False
            rlp = k.get("rate_limit_per_minute")
            if not isinstance(rlp, int) or rlp < 0:
                return False
            if rlp > 0 and _count_calls_last_minute(k["id"]) >= rlp:
                return False
            q = k.get("quota_calls_per_day")
            if not isinstance(q, int) or q < 0:
                return False
            u = _get_or_create_usage_row(k["id"])
            return (u.get("calls_total", 0) + 1) <= q

        for k in candidates:
            if usable(k):
                return k, None

        record_key = None
        for k in candidates:
            if k.get("status") == "active" and _key_allows_tool(k):
                record_key = k
                break
        if record_key is None:
            record_key = candidates[0]

        if record_key.get("status") != "active":
            return record_key, ("KEY_INACTIVE", "API key is not active", "UNAUTHORIZED")
        if not _key_allows_tool(record_key):
            return record_key, ("TOOL_NOT_ALLOWED", f"tool '{TOOL}' not allowed for this API key", "UNAUTHORIZED")

        rlp = record_key.get("rate_limit_per_minute")
        if isinstance(rlp, int) and rlp > 0 and _count_calls_last_minute(record_key["id"]) >= rlp:
            return record_key, ("RATE_LIMITED", "too many requests; retry after 1s", "RATE_LIMIT")

        q = record_key.get("quota_calls_per_day")
        if isinstance(q, int) and q >= 0:
            u = _get_or_create_usage_row(record_key["id"])
            if u.get("calls_total", 0) + 1 > q:
                return record_key, ("QUOTA_EXCEEDED", "daily call quota exceeded for UTC date", "QUOTA_EXCEEDED")

        return record_key, ("UNAUTHORIZED", "no available API key could authorize this request", "UNAUTHORIZED")

    def _create_execution(api_key_id, status, request_params, result_number=None, result_meta=None, error_code=None, error_message=None):
        eid = _gen_id("mmx")
        row = {
            "id": eid,
