    return {"result": result, "execution_id": ex["id"]}

def listApiKeys(owner=None, status=None, nameContains=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0496000" if __import__("os").path.isdir("./environment_mix/0496000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate inputs
    if owner is not None and not isinstance(owner, str):
        return _err("VALIDATION_ERROR", "`owner` must be a string.")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "`status` must be a string.")
        if status not in ("active", "suspended", "revoked"):
            return _err("VALIDATION_ERROR", "`status` must be one of: active, suspended, revoked.")
    if nameContains is not None and not isinstance(nameContains, str):
        return _err("VALIDATION_ERROR", "`nameContains` must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "`limit` must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "`cursor` must be a string.")

    api_keys = _load("api_keys.json")
    executions = _load("tool_executions.json")
    usage_daily = _load("usage_daily.json")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _day_bucket_iso(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        d = dt.date()
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        # ids for executions/usage not created here; only tool_executions required for every call
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _ensure_usage_row(api_key_id, date_iso):
        for r in usage_daily:
            if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("date") == date_iso:
                return r
        row = {
            "id": _gen_id("mmu"),
            "api_key_id": api_key_id,
            "date": date_iso,
            "calls_total": 0,
            "calls_succeeded": 0,
            "calls_failed": 0,
            "numbers_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
            "status": "open",
        }
        usage_daily.append(row)
        return row

    def _count_recent_calls(api_key_id, window_seconds=60):
        window_start = now - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for e in executions:
            if not isinstance(e, dict):
                continue
            if e.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(e.get("created_at"))
            if created is None:
                continue
            if created >= window_start:
                cnt += 1
        return cnt

    # Ambient authentication: choose an active key that can successfully call this administrative tool.
    # Since listApiKeys isn't in allowed_tools enum, we treat it as permitted for any active key.
    auth_key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str) and k.get("id"):
            # ensure quota/rate fields exist for proper accounting
            if isinstance(k.get("quota_calls_per_day"), int) and isinstance(k.get("rate_limit_per_minute"), int):
                auth_key = k
                break
    if auth_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    api_key_id = auth_key["id"]
    date_iso = _day_bucket_iso(now)
    usage_row = _ensure_usage_row(api_key_id, date_iso)

    # Create tool_executions row for this call (required for every tool call); treat as tool_name="max" is invalid,
    # so we do not record tool_executions for listApiKeys (not part of tool_name enum). Observable dynamics still required,
    # but schema only provides tool_executions. We'll log usage counters only for this endpoint via usage_daily.
    # (If tool_executions strictly required only for math tools per business rules, do not create invalid enum rows.)

    # Rate limit & quota enforcement still applied via usage/executions counts.
    per_minute = int(auth_key.get("rate_limit_per_minute", 0))
    if per_minute == 0:
        usage_row["calls_total"] = int(usage_row.get("calls_total", 0)) + 1
        usage_row["calls_failed"] = int(usage_row.get("calls_failed", 0)) + 1
        usage_row["updated_at"] = now_iso
        _save("usage_daily.json", usage_daily)
        return _err("RATE_LIMIT", "too many requests; retry after 1s")
    if _count_recent_calls(api_key_id, 60) > per_minute:
        usage_row["calls_total"] = int(usage_row.get("calls_total", 0)) + 1
        usage_row["calls_failed"] = int(usage_row.get("calls_failed", 0)) + 1
        usage_row["updated_at"] = now_iso
        _save("usage_daily.json", usage_daily)
        return _err("RATE_LIMIT", "too many requests; retry after 1s")

    quota_day = int(auth_key.get("quota_calls_per_day", 0))
    if quota_day == 0 or (int(usage_row.get("calls_total", 0)) + 1) > quota_day:
        usage_row["calls_total"] = int(usage_row.get("calls_total", 0)) + 1
        usage_row["calls_failed"] = int(usage_row.get("calls_failed", 0)) + 1
        usage_row["updated_at"] = now_iso
        _save("usage_daily.json", usage_daily)
        return _err("QUOTA_EXCEEDED", "daily call quota exceeded for UTC date")

    # Apply filters
    rows = [k for k in api_keys if isinstance(k, dict)]
    if owner is not None:
        rows = [k for k in rows if k.get("owner") == owner]
    if status is not None:
        rows = [k for k in rows if k.get("status") == status]
    if nameContains is not None:
        sub = nameContains.lower()
        rows = [k for k in rows if isinstance(k.get("name"), str) and sub in k["name"].lower()]

    # Sort by id for stable pagination
    rows.sort(key=lambda r: (r.get("id") or ""))

    start_idx = 0
    if cursor is not None and cursor != "":
        # Cursor is an opaque string; accept any existing id as cursor. If not found, treat as empty (no error).
        found = False
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start_idx = i + 1
                found = True
                break
        if not found:
            start_idx = 0

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(rows)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    # Usage accounting: count this call as succeeded (it's an authenticated read)
    usage_row["calls_total"] = int(usage_row.get("calls_total", 0)) + 1
    usage_row["calls_succeeded"] = int(usage_row.get("calls_succeeded", 0)) + 1
    usage_row["updated_at"] = now_iso
    _save("usage_daily.json", usage_daily)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "object": "list",
        "data": page,
        "meta": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "latency_ms": latency_ms},
    }

def createApiKey(name, owner, allowed_tools=None, quota_calls_per_day=None, quota_numbers_per_call_max=None, rate_limit_per_minute=None, **_extra):
    import json, os, datetime, time, uuid, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0496000" if __import__("os").path.isdir("./environment_mix/0496000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    TOOL_ENUM = ["add", "subtract", "multiply", "division", "sum", "mean", "median", "mode", "min", "max", "floor", "ceiling", "round"]

    # Validate
    if not isinstance(name, str) or not (1 <= len(name) <= 200):
        return _err("VALIDATION_ERROR", "`name` must be a string with length 1..200.")
    if not isinstance(owner, str) or not (1 <= len(owner) <= 200):
        return _err("VALIDATION_ERROR", "`owner` must be a string with length 1..200.")
    if allowed_tools is None:
        allowed_tools = []
    if not isinstance(allowed_tools, list) or any((not isinstance(t, str) or t not in TOOL_ENUM) for t in allowed_tools):
        return _err("VALIDATION_ERROR", "`allowed_tools` must be an array of known tool names.")
    if quota_calls_per_day is None:
        quota_calls_per_day = 10000
    if quota_numbers_per_call_max is None:
        quota_numbers_per_call_max = 100
    if rate_limit_per_minute is None:
        rate_limit_per_minute = 60
    if not isinstance(quota_calls_per_day, int) or quota_calls_per_day < 0:
        return _err("VALIDATION_ERROR", "`quota_calls_per_day` must be an integer >= 0.")
    if not isinstance(quota_numbers_per_call_max, int) or quota_numbers_per_call_max < 1:
        return _err("VALIDATION_ERROR", "`quota_numbers_per_call_max` must be an integer >= 1.")
    if not isinstance(rate_limit_per_minute, int) or rate_limit_per_minute < 0:
        return _err("VALIDATION_ERROR", "`rate_limit_per_minute` must be an integer >= 0.")

    api_keys = _load("api_keys.json")

    # Ambient auth: accept if any active key exists (do not invent forbidden checks)
    authed = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str) and k.get("id"):
            authed = k
            break
    if authed is None:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    # Enforce uniqueness(key_prefix)
    # Generate one-time secret; store only hash; return plaintext once.
    secret_token = "mmk_live_" + secrets.token_urlsafe(24)
    key_prefix = secret_token[:8]

    existing_prefixes = {k.get("key_prefix") for k in api_keys if isinstance(k, dict)}
    # regenerate if collision
    tries = 0
    while key_prefix in existing_prefixes and tries < 10:
        secret_token = "mmk_live_" + secrets.token_urlsafe(24)
        key_prefix = secret_token[:8]
        tries += 1
    if key_prefix in existing_prefixes:
        return _err("CONFLICT", "Unable to allocate unique key prefix; retry.")

    # Hash (best-effort, but never authenticate by this)
    key_hash = hashlib.sha256(secret_token.encode("utf-8")).hexdigest()

    new_id = f"mmk_{uuid.uuid4().hex}"
    row = {
        "id": new_id,
        "key_prefix": key_prefix,
        "key_hash": key_hash,
        "name": name,
        "owner": owner,
        "status": "active",
        "allowed_tools": allowed_tools,
        "quota_calls_per_day": quota_calls_per_day,
        "quota_numbers_per_call_max": quota_numbers_per_call_max,
        "rate_limit_per_minute": rate_limit_per_minute,
        "last_used_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    api_keys.append(row)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "api_key": row,
        "secret": secret_token,
        "meta": {"one_time_secret": True, "latency_ms": latency_ms},
    }

def updateApiKey(id, name=None, allowed_tools=None, quota_calls_per_day=None, quota_numbers_per_call_max=None, rate_limit_per_minute=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0496000" if __import__("os").path.isdir("./environment_mix/0496000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    TOOL_ENUM = ["add", "subtract", "multiply", "division", "sum", "mean", "median", "mode", "min", "max", "floor", "ceiling", "round"]
    TRANSITIONS = {
        "active": ["suspended", "revoked"],
        "suspended": ["active", "revoked"],
        "revoked": []
    }

    # Validate
    if not isinstance(id, str) or not id:
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string.")
    if name is not None and (not isinstance(name, str) or not (1 <= len(name) <= 200)):
        return _err("VALIDATION_ERROR", "`name` must be a string with length 1..200.")
    if allowed_tools is not None:
        if not isinstance(allowed_tools, list) or any((not isinstance(t, str) or t not in TOOL_ENUM) for t in allowed_tools):
            return _err("VALIDATION_ERROR", "`allowed_tools` must be an array of known tool names.")
    if quota_calls_per_day is not None and (not isinstance(quota_calls_per_day, int) or quota_calls_per_day < 0):
        return _err("VALIDATION_ERROR", "`quota_calls_per_day` must be an integer >= 0.")
    if quota_numbers_per_call_max is not None and (not isinstance(quota_numbers_per_call_max, int) or quota_numbers_per_call_max < 1):
        return _err("VALIDATION_ERROR", "`quota_numbers_per_call_max` must be an integer >= 1.")
    if rate_limit_per_minute is not None and (not isinstance(rate_limit_per_minute, int) or rate_limit_per_minute < 0):
        return _err("VALIDATION_ERROR", "`rate_limit_per_minute` must be an integer >= 0.")
    if status is not None and (not isinstance(status, str) or status not in ("active", "suspended", "revoked")):
        return _err("VALIDATION_ERROR", "`status` must be one of: active, suspended, revoked.")

    api_keys = _load("api_keys.json")

    # Ambient auth: accept if any active key exists (do not invent forbidden checks)
    authed = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str) and k.get("id"):
            authed = k
            break
    if authed is None:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    # Find target
    target = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == id:
            target = k
            break
    if target is None:
        return _err("NOT_FOUND", "API key not found.")

    # Apply updates
    if name is not None:
        target["name"] = name
    if allowed_tools is not None:
        target["allowed_tools"] = allowed_tools
    if quota_calls_per_day is not None:
        target["quota_calls_per_day"] = quota_calls_per_day
    if quota_numbers_per_call_max is not None:
        target["quota_numbers_per_call_max"] = quota_numbers_per_call_max
    if rate_limit_per_minute is not None:
        target["rate_limit_per_minute"] = rate_limit_per_minute

    if status is not None and status != target.get("status"):
        cur = target.get("status")
        if cur not in TRANSITIONS:
            return _err("VALIDATION_ERROR", "Invalid current status on record.")
        if status not in TRANSITIONS[cur]:
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}.")
        target["status"] = status

    target["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {"api_key": target, "meta": {"latency_ms": latency_ms}}

def listToolExecutions(api_key_id=None, tool_name=None, status=None, created_at_gte=None, created_at_lte=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0496000" if __import__("os").path.isdir("./environment_mix/0496000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    TOOL_ENUM = ["add", "subtract", "multiply", "division", "sum", "mean", "median", "mode", "min", "max", "floor", "ceiling", "round"]
    STATUS_ENUM = ["received", "validated", "succeeded", "failed"]

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an ISO8601 date-time string")
        try:
            # Accept 'Z'
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be an ISO8601 date-time string")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "created_at" not in obj or "id" not in obj:
                return _err("VALIDATION_ERROR", "cursor is invalid")
            ca = obj["created_at"]
            _id = obj["id"]
            if not isinstance(ca, str) or not isinstance(_id, str):
                return _err("VALIDATION_ERROR", "cursor is invalid")
            p = _parse_dt(ca, "cursor.created_at")
            if isinstance(p, dict) and "error" in p:
                return p
            return {"created_at": p, "id": _id}
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError, base64.binascii.Error):
            return _err("VALIDATION_ERROR", "cursor is invalid")

    def _encode_cursor(created_at_iso, _id):
        payload = json.dumps({"created_at": created_at_iso, "id": _id}, ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Validate basic params
    if api_key_id is not None and not isinstance(api_key_id, str):
        return _err("VALIDATION_ERROR", "api_key_id must be a string")
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in TOOL_ENUM:
            return _err("VALIDATION_ERROR", "tool_name is invalid", allowed=TOOL_ENUM)
    if status is not None:
        if not isinstance(status, str) or status not in STATUS_ENUM:
            return _err("VALIDATION_ERROR", "status is invalid", allowed=STATUS_ENUM)
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    gte = _parse_dt(created_at_gte, "created_at_gte")
    if isinstance(gte, dict) and "error" in gte:
        return gte
    lte = _parse_dt(created_at_lte, "created_at_lte")
    if isinstance(lte, dict) and "error" in lte:
        return lte
    if gte and lte and gte > lte:
        return _err("VALIDATION_ERROR", "created_at_gte must be <= created_at_lte")

    cur = _decode_cursor(cursor)
    if isinstance(cur, dict) and "error" in cur:
        return cur

    api_keys = _load("api_keys.json")
    executions = _load("tool_executions.json")
    usage_daily = _load("usage_daily.json")

    # Ambient auth resolution: pick any active key that can call this tool (allowed_tools empty or includes it).
    # If api_key_id provided, authenticate/authorize with that key; else pick one.
    authed_key = None
    if api_key_id is not None:
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                authed_key = k
                break
        if authed_key is None:
            # still must log attempt? no api_key_id; can't. Return UNAUTHORIZED.
            return _err("UNAUTHORIZED", "API key is missing/invalid")
        if authed_key.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is missing/invalid")
        allowed = authed_key.get("allowed_tools")
        if isinstance(allowed, list) and len(allowed) > 0 and "listToolExecutions" in TOOL_ENUM:
            # unreachable; listToolExecutions not part of allowed_tools enum
            pass
        # There's no explicit permission model in schema; implement "FORBIDDEN" by restricting visibility to own key.
        # If caller tries to filter other api_key_id (not possible since using same param), allow only own.
        # This endpoint's filter api_key_id is overloaded: also used for auth.
        # So no additional forbidden check needed.
    else:
        # Search for any key that is active. No "listToolExecutions" in allowed_tools enum, so treat as admin/internal:
        # allow if allowed_tools is empty (all tools allowed) OR any key is active.
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                authed_key = k
                break
        if authed_key is None:
            return _err("UNAUTHORIZED", "API key is missing/invalid")

    # Enforce quota/rate limits based on usage_daily and tool_executions.
    # Since this tool is not in tool_name enum, we only enforce rate/quota if possible by counting calls in tool_executions today
    # for this api_key_id as a proxy. This service schema declares quotas for tool calls; we treat audit endpoint as a call too.
    # To keep dynamics observable, we record a tool_executions row under a synthetic tool_name? Not allowed by enum.
    # Therefore, log to usage_daily only (no schema field for endpoint logs). We'll enforce via tool_executions counts.
    # If there is no matching bucket in usage_daily, create on completion.
    def _date_bucket(dt):
        d = dt.astimezone(datetime.timezone.utc).date()
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    bucket = _date_bucket(now)
    bucket_iso = bucket.isoformat()

    # Find or create usage row
    usage_row = None
    for u in usage_daily:
        if isinstance(u, dict) and u.get("api_key_id") == authed_key.get("id") and u.get("date") == bucket_iso:
            usage_row = u
            break
    if usage_row is None:
        usage_row = {
            "id": f"ud_{authed_key.get('id')}_{bucket.date().isoformat()}",
            "api_key_id": authed_key.get("id"),
            "date": bucket_iso,
            "calls_total": 0,
            "calls_succeeded": 0,
            "calls_failed": 0,
            "numbers_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        usage_daily.append(usage_row)

    # Daily quota
    q = authed_key.get("quota_calls_per_day")
    if not isinstance(q, int) or q < 0:
        return _err("VALIDATION_ERROR", "API key quota_calls_per_day is misconfigured")
    if usage_row.get("calls_total", 0) + 1 > q:
        # Record the failed "call" in usage_daily
        usage_row["calls_total"] = int(usage_row.get("calls_total", 0)) + 1
        usage_row["calls_failed"] = int(usage_row.get("calls_failed", 0)) + 1
        usage_row["updated_at"] = now_iso
        _save("usage_daily.json", usage_daily)
        return _err("QUOTA_EXCEEDED", "Daily call quota exceeded")

    # Rate limit per minute: approximate using tool_executions created_at in last 60s for this key
    r = authed_key.get("rate_limit_per_minute")
    if not isinstance(r, int) or r < 0:
        return _err("VALIDATION_ERROR", "API key rate_limit_per_minute is misconfigured")
    if r > 0:
        window_start = now - datetime.timedelta(seconds=60)
        c = 0
        for ex in executions:
            if not isinstance(ex, dict):
                continue
            if ex.get("api_key_id") != authed_key.get("id"):
                continue
            ca = ex.get("created_at")
            if not isinstance(ca, str):
                continue
            pd = _parse_dt(ca, "created_at")
            if isinstance(pd, dict) and "error" in pd:
                continue
            if pd >= window_start:
                c += 1
        if c + 1 > r:
            usage_row["calls_total"] = int(usage_row.get("calls_total", 0)) + 1
            usage_row["calls_failed"] = int(usage_row.get("calls_failed", 0)) + 1
            usage_row["updated_at"] = now_iso
            _save("usage_daily.json", usage_daily)
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # Apply filters
    filtered = []
    for ex in executions:
        if not isinstance(ex, dict):
            continue
        # Visibility: only own api_key_id unless authenticated key is treated as admin. No admin flag in schema.
        # Implement strict: caller sees only executions for their api_key_id.
        if ex.get("api_key_id") != authed_key.get("id"):
            continue

        if tool_name is not None and ex.get("tool_name") != tool_name:
            continue
        if status is not None and ex.get("status") != status:
            continue

        ca = ex.get("created_at")
        if isinstance(ca, str):
            pca = _parse_dt(ca, "created_at")
            if isinstance(pca, dict) and "error" in pca:
                continue
            if gte and pca < gte:
                continue
            if lte and pca > lte:
                continue
        else:
            # if no created_at, skip
            continue
        filtered.append(ex)

    # Sort newest-first by created_at then id
    def _sort_key(ex):
        ca = ex.get("created_at")
        pca = _parse_dt(ca, "created_at")
        if isinstance(pca, dict) and "error" in pca:
            pca = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (pca, ex.get("id") or "")

    filtered.sort(key=_sort_key, reverse=True)

    # Cursor pagination
    start_index = 0
    if cur is not None:
        # find first item strictly older than cursor (created_at,id) in this sort order
        for i, ex in enumerate(filtered):
            ca = ex.get("created_at")
            pca = _parse_dt(ca, "created_at")
            if isinstance(pca, dict) and "error" in pca:
                continue
            ex_id = ex.get("id")
            # Since sorted desc, we want items after the cursor tuple
            if (pca < cur["created_at"]) or (pca == cur["created_at"] and isinstance(ex_id, str) and ex_id < cur["id"]):
                start_index = i
                break
        else:
            start_index = len(filtered)

    page = filtered[start_index:start_index + limit]
    has_more = start_index + limit < len(filtered)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(last.get("created_at"), last.get("id"))

    # Record observable usage dynamics: count this read as a succeeded call with 0 numbers.
    usage_row["calls_total"] = int(usage_row.get("calls_total", 0)) + 1
    usage_row["calls_succeeded"] = int(usage_row.get("calls_succeeded", 0)) + 1
    usage_row["updated_at"] = now_iso
    _save("usage_daily.json", usage_daily)

    # Update key last_used_at for successful authenticated request
    authed_key["last_used_at"] = now_iso
    authed_key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data": {
            "items": page,
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        },
        "meta": {
            "api_key_id": authed_key.get("id"),
            "latency_ms": latency_ms
        }
    }

def redactExecutionNumbers(execution_id, reason=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0496000" if __import__("os").path.isdir("./environment_mix/0496000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    now = _utcnow()
    now_iso = _isoz(now)

    # Validate inputs (accept reason of other types by coercing to string, but enforce max length if present)
    if not isinstance(execution_id, str) or not execution_id.strip():
        return _err("VALIDATION_ERROR", "'execution_id' must be a non-empty string")
    execution_id = execution_id.strip()

    if reason is not None and not isinstance(reason, str):
        # Relax to accept e.g. integer reasons (audit indicates reason=6 used)
        try:
            reason = str(reason)
        except Exception:
            reason = None
    if isinstance(reason, str) and len(reason) > 500:
        return _err("VALIDATION_ERROR", "'reason' exceeds maxLength 500")

    api_keys = _load("api_keys.json")
    exec_rows = _load("tool_executions.json")
    execution_numbers_rows = _load("execution_numbers.json")

    if not isinstance(api_keys, list) or not isinstance(exec_rows, list) or not isinstance(execution_numbers_rows, list):
        return _err("NOT_FOUND", "Datastore is not initialized")

    # Ambient auth: pick an API key that can perform redaction (best-effort; tool is not in allowed_tools enum, so treat allow-list as math-only)
    # Use any active key; if none, UNAUTHORIZED.
    api_key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active":
            api_key = k
            break
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this operation")

    # Find execution (must exist)
    execution = None
    for e in exec_rows:
        if isinstance(e, dict) and e.get("id") == execution_id:
            execution = e
            break
    if execution is None:
        return _err("NOT_FOUND", "Execution not found", execution_id=execution_id)

    # FORBIDDEN rule: permit only if caller owns the execution's api_key_id (best available in this datastore model)
    if execution.get("api_key_id") != api_key.get("id"):
        return _err("UNAUTHORIZED", "Caller not permitted to redact this execution", execution_id=execution_id)

    # Locate child numbers
    children = [r for r in execution_numbers_rows if isinstance(r, dict) and r.get("execution_id") == execution_id]
    if not children:
        # Execution exists; numbers may never have been recorded (non-array tool), treat as conflict-free no-op? spec says redact stored input numbers
        return _err("NOT_FOUND", "No stored input numbers for this execution", execution_id=execution_id)

    # Check already deleted
    if all((c.get("status") == "deleted") for c in children):
        return _err("CONFLICT", "Execution numbers already deleted", execution_id=execution_id)

    # Transition active -> deleted
    changed = 0
    for c in children:
        if c.get("status") == "active":
            c["status"] = "deleted"
            c["updated_at"] = now_iso
            changed += 1

    if changed == 0:
        return _err("CONFLICT", "No active execution numbers to redact", execution_id=execution_id)

    # Persist
    _save("execution_numbers.json", execution_numbers_rows)

    return {
        "execution_id": execution_id,
        "redacted_count": changed,
        "status": "succeeded",
        "reason": reason,
        "latency_ms": max(0, int((time.time() - t0) * 1000)),
        "updated_at": now_iso,
    }
